void main() {
  // var - можно изменять
  var age = 20;
  age = 21; // ✅ Работает
  print('Возраст: $age');

  // final - устанавливается один раз
  final name = 'Асет';
  // name = 'Айгерим'; // ❌ Ошибка!
  print('Имя: $name');

  // const - константа
  const pi = 3.14159;
  // pi = 3.14; // ❌ Ошибка!
  print('Число Пи: $pi');

  // final vs const
  final currentTime = DateTime.now(); // ✅ Работает
  // const currentTime2 = DateTime.now(); // ❌ Ошибка!
}

void main() {
  // Целые числа (int)
  int age = 25;
  int temperature = -10;

  // Дробные числа (double)
  double price = 99.99;
  double pi = 3.14159;

  // Арифметические операции
  int sum = 10 + 5;        // 15
  int diff = 10 - 5;       // 5
  int product = 10 * 5;    // 50
  double quotient = 10 / 3; // 3.333...
  int intDiv = 10 ~/ 3;    // 3
  int remainder = 10 % 3;   // 1

  print('Сумма: $sum');
  print('Деление: $quotient');
  print('Целочисленное: $intDiv');

  // Полезные методы
  double num = -5.7;
  print('Модуль: ${num.abs()}');      // 5.7
  print('Округление: ${num.round()}'); // -6
  print('Вверх: ${num.ceil()}');      // -5
  print('Вниз: ${num.floor()}');      // -6
}

void main() {
  // Создание строк
  String name = 'Асет';
  String city = "Алматы";

  // Интерполяция
  int age = 20;
  print('Меня зовут $name');
  print('Мне ${age + 1} лет');

  // Свойства и методы
  String text = '  Привет, Мир!  ';
  print('Длина: ${text.length}');  // 16
  print('Верхний регистр: ${text.toUpperCase()}');
  print('Нижний регистр: ${text.toLowerCase()}');
  print('Без пробелов: "${text.trim()}"');

  // Проверки
  print(text.contains('Мир'));     // true
  print(text.startsWith('При'));   // false (есть пробелы)
  print(text.trim().startsWith('При')); // true

  // Работа с подстроками
  String greeting = 'Привет, мир!';
  print(greeting.substring(0, 6));  // Привет
  print(greeting.replaceAll('мир', 'Dart')); // Привет, Dart!
}

void main() {
  // Логические значения
  bool isStudent = true;
  bool hasLicense = false;

  // Операторы сравнения
  int age = 20;
  bool isAdult = age >= 18;        // true
  bool isTeenager = age >= 13 && age <= 19; // false

  print('Совершеннолетний: $isAdult');
  print('Подросток: $isTeenager');

  // Логические операторы
  bool canDrive = age >= 18 && hasLicense;
  bool needsPermission = age < 18 || !hasLicense;

  print('Может водить: $canDrive');
  print('Нужно разрешение: $needsPermission');

  // Инверсия
  bool isNotStudent = !isStudent;  // false
  print('Не студент: $isNotStudent');

  // Сложные условия
  int score = 85;
  bool passedExam = score >= 60 && score <= 100;
  bool excellentScore = score >= 90;

  print('Экзамен сдан: $passedExam');
  print('Отличный результат: $excellentScore');
}

void main() {
  // Создание списков
  var fruits = ['яблоко', 'банан', 'апельсин'];
  print('Фрукты: $fruits');

  // Доступ по индексу
  print('Первый фрукт: ${fruits[0]}');
  print('Последний: ${fruits[fruits.length - 1]}');

  // Изменение элемента
  fruits[1] = 'манго';
  print('После изменения: $fruits');

  // Добавление элементов
  fruits.add('виноград');
  fruits.insert(0, 'киви');
  print('После добавления: $fruits');

  // Удаление
  fruits.remove('манго');
  fruits.removeAt(0);
  print('После удаления: $fruits');

  // Проверки
  print('Длина списка: ${fruits.length}');
  print('Есть яблоко: ${fruits.contains("яблоко")}');
  print('Пустой: ${fruits.isEmpty}');

  // Полезные операции
  var numbers = [3, 1, 4, 1, 5];
  print('Первый: ${numbers.first}');
  print('Последний: ${numbers.last}');
  print('Перевернутый: ${numbers.reversed.toList()}');
}

void main() {
  // Создание множеств
  var numbers = {1, 2, 3, 2, 1}; // Дубликаты удаляются
  print('Числа: $numbers'); // {1, 2, 3}

  var fruits = {'яблоко', 'банан'};

  // Добавление
  fruits.add('апельсин');
  fruits.add('банан'); // Не добавится (уже есть)
  print('Фрукты: $fruits');

  // Проверки
  print('Есть яблоко: ${fruits.contains("яблоко")}');
  print('Количество: ${fruits.length}');

  // Операции над множествами
  var set1 = {1, 2, 3, 4};
  var set2 = {3, 4, 5, 6};

  print('Объединение: ${set1.union(set2)}');
  // {1, 2, 3, 4, 5, 6}

  print('Пересечение: ${set1.intersection(set2)}');
  // {3, 4}

  print('Разность: ${set1.difference(set2)}');
  // {1, 2}

  // Преобразование List -> Set (удаление дубликатов)
  var listWithDuplicates = [1, 2, 2, 3, 3, 3];
  var uniqueNumbers = listWithDuplicates.toSet();
  print('Уникальные: $uniqueNumbers'); // {1, 2, 3}
}

void main() {
  // Создание словаря
  var student = {
    'name': 'Асет',
    'age': 20,
    'course': 2,
    'university': 'КазНУ'
  };

  // Доступ к значениям
  print('Имя: ${student['name']}');
  print('Возраст: ${student['age']}');

  // Добавление и изменение
  student['gpa'] = 3.8;
  student['age'] = 21;
  print('Обновленный: $student');

  // Удаление
  student.remove('course');
  print('После удаления: $student');

  // Работа с ключами и значениями
  print('Ключи: ${student.keys}');
  print('Значения: ${student.values}');

  // Проверки
  print('Есть ключ name: ${student.containsKey("name")}');
  print('Есть значение 20: ${student.containsValue(20)}');
  print('Количество полей: ${student.length}');

  // Итерация по словарю
  student.forEach((key, value) {
    print('$key: $value');
  });

  // Оценки по предметам
  Map<String, int> grades = {
    'математика': 95,
    'физика': 88,
    'программирование': 92
  };
  print('\nОценки: $grades');
}

