void main() {
  // Non-nullable - не может быть null
  String name = 'Асет';
  // name = null; // ❌ Ошибка компиляции!
  print('Имя: $name');

  // Nullable - может быть null
  String? nickname = null;
  print('Никнейм: $nickname');

  // Safe call operator ?.
  String? city;
  print('Длина города: ${city?.length}'); // null (не ошибка!)

  city = 'Алматы';
  print('Длина города: ${city?.length}'); // 6

  // Null-coalescing operator ??
  String? username;
  String displayName = username ?? 'Гость';
  print('Отображаемое имя: $displayName'); // Гость

  username = 'aset_dev';
  displayName = username ?? 'Гость';
  print('Отображаемое имя: $displayName'); // aset_dev

  // Null-aware assignment ??=
  String? greeting;
  greeting ??= 'Привет!';
  print('Приветствие 1: $greeting'); // Привет!

  greeting ??= 'Здравствуй!';
  print('Приветствие 2: $greeting'); // Привет! (не изменилось)

  // Not-null assertion !
  String? email = 'test@example.com';
  int emailLength = email!.length; // Уверены что не null
  print('Длина email: $emailLength');

  // Late переменные - инициализация позже
  late String lateVar;
  lateVar = 'Инициализировано позже';
  print('Late переменная: $lateVar');
}

void main() {
  // var - тип фиксируется при инициализации
  var varExample = 10; // int
  print('var пример: $varExample');
  // varExample = 'text'; // ❌ Ошибка компиляции!

  // dynamic - тип может меняться
  dynamic dynExample = 10;
  print('dynamic как int: $dynExample');

  dynExample = 'Теперь строка!';
  print('dynamic как String: $dynExample');

  dynExample = true;
  print('dynamic как bool: $dynExample');

  dynExample = [1, 2, 3];
  print('dynamic как List: $dynExample');

  // Object - базовый тип
  Object objExample = 10;
  print('Object пример: $objExample');

  objExample = 'Тоже можно менять тип';
  print('Object как String: $objExample');

  // Но нельзя вызывать методы без приведения типа
  // int length = objExample.length; // ❌ Ошибка!

  // Проверка типа с is
  dynamic value = 'Привет, Dart!';

  if (value is String) {
    print('Это строка, длина: ${value.length}');
  } else if (value is int) {
    print('Это число');
  }

  // Явное приведение типа с as
  dynamic numValue = 42;
  int number = numValue as int;
  print('Приведено к int: $number');

  // Практический пример - JSON
  dynamic jsonData = {
    'name': 'Асет',
    'age': 20,
    'isStudent': true,
    'scores': [95, 88, 92]
  };

  print('\n=== JSON Данные ===');
  print('Имя: ${jsonData['name']}');
  print('Возраст: ${jsonData['age']}');
  print('Студент: ${jsonData['isStudent']}');
  print('Оценки: ${jsonData['scores']}');

  // Безопасная работа с dynamic
  dynamic unsafeValue = 'test';

  if (unsafeValue is int) {
    int safeValue = unsafeValue;
    print('Безопасное int значение: $safeValue');
  } else {
    print('Значение не int, а ${unsafeValue.runtimeType}');
  }
}
